import {chromium} from 'playwright';import {mkdir,writeFile} from 'node:fs/promises';
const folder='diagnostics/education-official-route-20261115';await mkdir(folder,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH}),report={runUrl:'https://github.com/hossambahr229-star/hossambahr-site/actions/runs/'+process.env.GITHUB_RUN_ID,scope:'Read-only anonymous government service identification; no form submission or login',results:[]};
try{for(const [key,url] of [['current','https://moe.gov.ae/ar/eservices/servicecard/pages/certificateequilizationverification.aspx'],['ministry','https://www.mohesr.gov.ae/en/EServices/ServiceCard/pages/CertificateEquilizationVerification.aspx'],['verification','https://pes.moe.gov.ae/en/verification']]){const page=await browser.newPage({viewport:{width:1440,height:900}});let status,error;try{status=(await page.goto(url,{waitUntil:'domcontentloaded',timeout:30000}))?.status();await page.waitForLoadState('networkidle',{timeout:12000}).catch(()=>{});}catch(e){error=String(e).slice(0,200);}let dom={};try{dom=await page.evaluate(()=>({url:location.href,title:document.title,text:document.body.innerText.slice(0,18000),headings:[...document.querySelectorAll('h1,h2,h3')].map(h=>h.innerText),links:[...document.querySelectorAll('a[href]')].filter(a=>/start|apply|verification|certificate|ابدأ|بدء|تحقق|معادل/i.test(a.innerText+' '+a.href)).map(a=>({text:a.innerText,url:a.href})).slice(0,35)}));await page.screenshot({path:folder+'/'+key+'.jpg',type:'jpeg',quality:80,fullPage:true});}catch(e){dom.error=String(e).slice(0,150);}report.results.push({key,requested:url,status,error,...dom});await page.close();}}finally{await browser.close();await writeFile(folder+'/report.json',JSON.stringify(report,null,2));}console.log(JSON.stringify(report));
